import os
import joblib
import pandas as pd
from feature_extraction import extract_features

def main():
    print("==================================================")
    print("    WELCOME TO THE PHISHING URL DETECTION SYSTEM   ")
    print("==================================================")
    
    # 1. Load the saved model file generated by your training script
    model_path = os.path.join('models', 'phishing_model.pkl')
    
    if not os.path.exists(model_path):
        print("\n[ERROR] Model file not found! Please run 'train_model.py' first to build the model brain.")
        return
        
    print("Loading predictive intelligence model...")
    model = joblib.load(model_path)
    print("System active and ready for evaluation.\n")
    
    while True:
        # 2. Get input URL string from user
        user_url = input("Enter a URL to analyze (or type 'quit' to exit): ").strip()
        
        if user_url.lower() == 'quit':
            print("Exiting application. Goodbye!")
            break
            
        if not user_url:
            print("Input cannot be empty. Please try again.")
            continue
            
        # 3. Process features for the individual input string
        features = extract_features(user_url)
        
        # Format the features into a single row DataFrame matching training shape
        input_data = pd.DataFrame([features])
        
        # 4. Predict using the trained model
        prediction = model.predict(input_data)[0]
        
        # 5. Display the classification outcome results clearly
        print("\n---------------- Analysis Results ----------------")
        print(f"Target URL: {user_url}")
        
        # 1 means Phishing, 0 means Safe/Legitimate
        if prediction == 1:
            print("Classification Verdict: 🚨 SUSPICIOUS / PHISHING TARGET DETECTED!")
        else:
            print("Classification Verdict: ✅ LEGINIMATE / SAFE WEBSITE")
            
        # 6. Show the internal reason logic metrics
        print("\nContributing Features Detected Details:")
        print(f" -> Character Length: {features['url_length']} characters")
        print(f" -> Quantity of Dots: {features['qty_dots']}")
        print(f" -> Uses Raw IP Address Instead of Name: {'Yes' if features['is_ip'] == 1 else 'No'}")
        print(f" -> Lacks Secure HTTPS Link Protocol: {'Yes' if features['is_http'] == 1 else 'No'}")
        print(f" -> Contains Risk Keywords (e.g. login/verify): {'Yes' if features['has_suspicious_keyword'] == 1 else 'No'}")
        print("--------------------------------------------------\n")

if __name__ == "__main__":
    main()
